import os
from openai import OpenAI

client = OpenAI(base_url="https://llm-gateway.example.internal/v1", api_key=os.environ["LITELLM_API_KEY"])

resp = client.responses.create(
    model="gpt-6-astra",
    reasoning={"effort": "medium"},  # low | medium | high | xhigh | max（沒有 none）
    tools=[{
        "type": "function",
        "name": "get_order_status",
        "description": "查詢訂單狀態",
        "parameters": {
            "type": "object",
            "properties": {"order_id": {"type": "string"}},
            "required": ["order_id"],
        },
    }],
    input="訂單 A123 目前的狀態？",
)
for item in resp.output:
    if item.type == "function_call":
        print(item.name, item.arguments)
